#include "Quests/MMOQuestDialogue.h"

namespace
{
	struct FEntry { const TCHAR* Accept; const TCHAR* TurnIn; };

	const TMap<FName, FEntry>& BuildTable()
	{
		static TMap<FName, FEntry> Table;
		if (Table.Num() > 0)
		{
			return Table;
		}
		Table.Add(FName(TEXT("Q_AbyssBastion")), { TEXT("Naibin onunde son bir siper var, evlat: yaylanin dogusuna dizilmis koruyucular. On ikisini devir; ardinda yalniz o golge kalacak."), TEXT("Siper yikildi, dogunun yolu acik. Al su Buyuk Can Iksirleri'ni ve soluklan; Naibin karsisina yorgun cikma.") });
		Table.Add(FName(TEXT("Q_AbyssDescent")), { TEXT("Kuzeybatida gezginlerin yuvasi var; ucurumdan oraya tirmanip yaylaya oradan yayiliyorlar. On ikisini dagit. Asagiya inen yolu goreceksin - bakma, yalniz dagit."), TEXT("Yuva dagildi. Gozun hala o yola takiliyorsa su Buyuk Mana Iksirleri'ni ic de kendine gel.") });
		Table.Add(FName(TEXT("Q_AbyssEdge")), { TEXT("Gezginler kiyidan yukari tirmaniyor; yaylanin bize kalan yarisini da istiyorlar. On ikisini geri it - kiyida adimini agirlastirmalarina izin verme."), TEXT("Kiyi yeniden bizim. Bu Buyuk Mana Iksirleri senin; dibi gorunmeyen yerde gucun tukenmesin.") });
		Table.Add(FName(TEXT("Q_AbyssGuardians")), { TEXT("Yaylanin obur ucunda koruyucular bekler; ucuruma inen yolu tutarlar. Besini devir. Kolay devrilmezler, son nefeslerinde ofkelenirler - geri cekilme."), TEXT("Koruyucular dustu. Ucurum Kaski'ni tak, evlat; asagidan gelen sesi duymamak icin degil, duyup da aldirmamak icin.") });
		Table.Add(FName(TEXT("Q_AbyssLine")), { TEXT("Koruyucularin ardinda bir hat daha var; altisini daha devir. Bu son hat, evlat. Ardinda bir naib bekliyor."), TEXT("Yol acik. Al su Ucurum Zirhi'ni. Yillar once sana tasiyabileceginden agirini vermem demistim; sozumu tuttum mu, artik bilemiyorum.") });
		Table.Add(FName(TEXT("Q_AbyssPatrol")), { TEXT("Kenar temiz dedik, ama gezginler devriye gibi doner durur; biri gidince oburu gelir. Onunun yolunu kes, evlat, kenari biraz daha biz tutalim."), TEXT("Devriye bozuldu. Al su iksirleri; kenarda yaralanan, gozunu asagiya dikmeye baslar.") });
		Table.Add(FName(TEXT("Q_AbyssRegent")), { TEXT("Naib, sahibinin yerine hukum surendir, evlat. Yaylanin dogusunda oturan o golge kimin adina konusuyorsa, fisiltiyi da onun adina yayiyor. Devir onu; dokunusu bedenini agirlastirir, ofkesi sona yaklastikca buyur. Ve donmeyi unutma."), TEXT("Duyuyor musun? Hicbir sey. Fisilti sustu, evlat... simdilik. Al su Ucurum Kilici'ni; naib dustu ama taht bos kalmaz. O gun geldiginde kilicin elinde olsun.") });
		Table.Add(FName(TEXT("Q_AbyssStriders")), { TEXT("Yillarca fisiltinin ormandan geldigini sandik, evlat. Ormanin kokleri, buzun kapisi, yazin yarigi - hepsi ayni bosluga aciliyormus. Ucurumun kenarinda gezginler dolasiyor; besini durdur. Dokunuslari adimini agirlastirir, kenarda agir adim tehlikelidir."), TEXT("Kenar temiz. Ucurum Botu'nu giy; dibi gorunmeyen yerde saglam basmak her seydir.") });
		Table.Add(FName(TEXT("Q_AbyssVigil")), { TEXT("Hat kirildi ama koruyucular yaylada nobetini surduruyor; sahipleri donecekmis gibi. Onunu bekle ve devir. Sabirli ol, evlat; nobetciyi ancak nobetci yener."), TEXT("Nobet dustu. Al su Buyuk Can Iksirleri'ni; Naibe giden yolda hepsine ihtiyacin olacak.") });
		Table.Add(FName(TEXT("Q_AshBinders")), { TEXT("Kulu buza, buzu kule baglayan baglayicilar var. Atesle kisi ayni ipe dizen bir el... Gumus Dal'in yaziti yine dogru cikti. Besini devir; vuruslari adimini agirlastirir, son nefeslerinde ofkelenirler."), TEXT("Ip gevsedi. Kul Kaski'ni tak; dumanin icinde basini dik, gozunu acik tut.") });
		Table.Add(FName(TEXT("Q_AshLine")), { TEXT("Baglayicilar karin ustune bir hat ormus; tek dugum kalsa yeniden orerler. Alti baglayici daha devir ki hat cozulsun."), TEXT("Hat cozuldu. Al su Kul Zirhi'ni; atesten de soguktan da gecmis birine yakisir.") });
		Table.Add(FName(TEXT("Q_AshMarchers")), { TEXT("Hat cozuldu sandik, ama kul yurumeyi bilir, evlat. Hattin ardindan yeni bir suru kaymis; agir adimli, ofkesi derinlerde. Sekizini durdur; canlari azaldikca yeniden alevlenirler."), TEXT("Yuruyenler durdu. Al su Buyuk Can Iksirleri'ni; ardindan gelen tirana daha dinc cikarsin.") });
		Table.Add(FName(TEXT("Q_AshOrcs")), { TEXT("Kul ovasinda orklar yeni bir kabile kurmus; derileri kavrulmus, gozleri dumanli. Kaldirdiklari kul adimini agirlastirir. Altisini dagit, yoksa vadiden tasacaklar."), TEXT("Ova temizlendi. Adamantin Kask'i tak; kulun icinde bile basini dik tut.") });
		Table.Add(FName(TEXT("Q_AshTyrant")), { TEXT("Hattin ucunda bir tiran oturuyor: Magma Tirani'nin kulunden dogmus, atesi sonmus ama hirsi sonmemis. Bir kez devirdigin seyi ikinci kez devirmek daha zordur, evlat - artik seni taniyor. Dokunusu yakar, cani azaldikca ofkelenir."), TEXT("Kul yagmuru durdu. Al su Kul Kilici'ni. Kuzeyde sis cekiliyor; yaylanin ortasinda bir bosluk var - fisilti oradan geliyor.") });
		Table.Add(FName(TEXT("Q_AshVanguard")), { TEXT("Kis Diyari'nin guneyinde kar griye donmus, evlat; gokten kul yagiyor. Alev Vadisi'nde sondurdugun ates olmemis, kule donup kuzeye yurumus. Onculerinden besini durdur; hizlidirlar, yaniklari derine isler."), TEXT("Onculer dustu ama kul hala yagiyor. Al su Kul Botu'nu; kor kapli karda bile ayagin saglam bassin.") });
		Table.Add(FName(TEXT("Q_AyazdisPatrol")), { TEXT("Buzulun kenarini tutan muhafizlarin nefesi kesildi, evlat. Onune cikan on dort canavari devir de devriye biraz soluklansin."), TEXT("Muhafizlar soluklandi. Su Buyuk Can Iksirleri senin; buzulda yorulan degil, kendini kollamayan duser.") });
		Table.Add(FName(TEXT("Q_Bandits")), { TEXT("Kirik Zincir'in artiklari ticaret yolunu kesiyor. Cogu Uzun Kis'ta her seyini kaybetmis adamlar; yine de kervana el kaldiranin hakki dorttur. Dordunu temizle."), TEXT("Yol acildi, kervanlar yeniden gelir. Onlara kin tutma, evlat; yoksulluk da bir fisiltidir.") });
		Table.Add(FName(TEXT("Q_Boss")), { TEXT("Daginik orklari tek bir yumruk altinda toplayan biri var: Ork Reisi. Fisiltinin ilk buyuk kilici o. Onu devir, evlat; Akcakule'ye yuruyusu bassiz kalsin."), TEXT("Reis dustu... Bu kasaba sana borclu. Al su Buyuk Kilic'i; kuzeyden esen ruzgar hala hayra alamet degil.") });
		Table.Add(FName(TEXT("Q_Cleanup")), { TEXT("Bolgede ciban gibi cogaldilar, evlat. Kim oldugu fark etmez, onune cikan ilk on canavari temizle; muhafizlar da biraz soluklansin."), TEXT("Bir sure rahat uyuruz. Ama fisilti dinmedikce yenileri cikar.") });
		Table.Add(FName(TEXT("Q_CrustWardens")), { TEXT("Cozulme Yolu'nda yari buz yari curuf kabuklu bekciler dikiliyor, evlat. Agir ve inatcidirlar; sekizini kir, canlari azaldikca ofkelendiklerini unutma."), TEXT("Kabuk catladi, yol acildi. Al su Buyuk Can Iksirleri'ni; ofkeli dusmana karsi sabir en iyi zirhtir.") });
		Table.Add(FName(TEXT("Q_CursedKnights")), { TEXT("O harabeler bir zamanlar bir sovalye tabyasiydi; Uzun Kis'ta son adamina dek dayandilar. Simdi fisilti onlari yeniden nobete kaldirmis. Besini yeminlerinden azat et; son nefeslerinde ofkelenirler, geri cekilme."), TEXT("Yeminleri bitti, huzurlari basladi. Al su Mithril Bot'u; buzda yolun kaymasin.") });
		Table.Add(FName(TEXT("Q_DireWolves")), { TEXT("Karakaya'nin kayaliklarinda siradan kurttan iri olanlar yuvalanmis; gozleri karanlikta kor gibi yanar. Dordunu devir, kokunu almadan once davran."), TEXT("Gozler sondu. Al su Celik Bot'u; kayalikta yolun sasmasin.") });
		Table.Add(FName(TEXT("Q_DuskGuardians")), { TEXT("Korunun yollarini agir bekciler tutuyor; yavastirlar ama bir darbede adimin agirlasir. Besini devir, golgede kaybolma."), TEXT("Yollar acildi. Alacakaranlik Botu'nu giy; isigin hic tam olmadigi yerde ayagin sasmasin.") });
		Table.Add(FName(TEXT("Q_DuskOverlord")), { TEXT("Korunun kalbinde hukum suren bir efendi var. Yillarca fisiltinin sahibi sandik onu. Devir onu, evlat; korunun alacakaranligi dagilsin."), TEXT("Koru aydinlandi... ama fisilti susmadi. Koklerden geliyordu, kuzeye cekildi. Al su Alacakaranlik Kilici'ni; Kuzey Yolu seni bekliyor.") });
		Table.Add(FName(TEXT("Q_DuskProwlers")), { TEXT("Gun ile gecenin arasindaki boslukta avlanan yaratiklar var, evlat; isiriklari zehirler. Korunun kiyisindan basla, besini durdur."), TEXT("Kiyi temiz. Al su Buyuk Can Iksirleri'ni; zehrin goturdugunu bunlar geri getirir.") });
		Table.Add(FName(TEXT("Q_DuskReavers")), { TEXT("Koruya siginan iri ork yagmacilar kervanlari soyuyor; yaralandikca cildirirlar. Besini dagit."), TEXT("Yagma bitti. Alacakaranlik Kaski senin; bu golgede bas dik durur.") });
		Table.Add(FName(TEXT("Q_DuskWraiths")), { TEXT("Korunun sisinde suzulen golgeler var; dokunuslari bedeni agirlastirir. Fisilti burada ninni gibidir, evlat. Besini kov, ninniyi dinleme."), TEXT("Sis inceldi, gozun acik kaldi. Al su Alacakaranlik Zirhi'ni; golge seni sahiplenmesin.") });
		Table.Add(FName(TEXT("Q_EmberHounds")), { TEXT("Buz Lordu dustugu gun dogu daglarindan duman yukseldi; bir yerde kis cekilince baska bir yerde ates uyandi. Alev Vadisi'nin gecidini kor tazilari tutuyor. Besini avla; isiriklari yakar, izleri kolay silinmez."), TEXT("Gecit acik. Al su sifa siselerini; bundan sonra her nefes sicak gelecek.") });
		Table.Add(FName(TEXT("Q_EmberPack")), { TEXT("Gecidi actin ama surunun artigi ardinda dolaniyor, evlat. Alti Kor Tazisi daha avla; yarali suru, saglamindan daha cok isirir."), TEXT("Suru dagildi, koku silindi. Al su Buyuk Can Iksirleri'ni; yanik iyilesir, dikkatsizlik iyilesmez.") });
		Table.Add(FName(TEXT("Q_FrostLich")), { TEXT("Iste buzun kalbi. Tahtinda oturan lord Uzun Kis'in ta kendisi mi, ondan dogan bir sey mi - bilmiyorum; bildigim, o nefes aldikca buzulun erimeyecegi. Git, devir onu; dokunusu seni dondurmaya, ofkesi ezmeye calisacak."), TEXT("Ruzgar dindi, evlat. Iki nesildir ilk kez. Al bu Mithril Kilic'i; hak ettin.") });
		Table.Add(FName(TEXT("Q_FrostWraiths")), { TEXT("Ork Reisi dustu, evlat, ama kuzeyden esen ruzgar hala olum kokuyor. Ayazdis'in sisinde Uzun Kis'in oluleri dolasiyor; bes Buz Hayaleti'ni dagit ki yol acilsin. Dokunuslarina dikkat et - adimini agirlastirirlar."), TEXT("Sis inceldi. Simdi buzun altindaki taslari gorebiliyorsun, degil mi?") });
		Table.Add(FName(TEXT("Q_FrostboundLine")), { TEXT("Dusen nobetcilerin yerine yenileri gecti; hat yirtilmadi, yalnizca inceldi. Alti nobetci daha devir ki Buz Kapisi'na giden yol acilsin. Hat dedigin, son halkasi kirilinca hat olmaktan cikar."), TEXT("Hat kirildi. Buzbagli Zirh artik senin; onu giyen yeminli degildir, ama yeminlilerden de geri kalmaz.") });
		Table.Add(FName(TEXT("Q_FrostboundOath")), { TEXT("Yeminliler hala kapiya sariliyor. Sekiz tanesini daha dagit; canlari azaldiginda yeminlerine daha siki tutunurlar, dikkat et."), TEXT("Son yemin de bozuldu. Al su Buyuk Can Iksirleri'ni; Buz Kapisi'na varmadan yaralarini sar.") });
		Table.Add(FName(TEXT("Q_FrostboundScouts")), { TEXT("Hukumdar dustu, firtina dindi; ama dinen firtina, ardinda saklanani gosterir, evlat. Diyarin kenarinda buzdan bir sinir var ve onu yeminli gozculer kolluyor. Besini sustur; hizlidirlar, dokunuslari adimini agirlastirir."), TEXT("Gozculer sustu; artik sinir seni gormeden sen onu goreceksin. Al su Buzbagli Bot'u, buzda iz birakma.") });
		Table.Add(FName(TEXT("Q_FrostboundSentinels")), { TEXT("Gozculerin ardinda nobetciler bekler; yavas yururler ama geri adim atmayi bilmezler. Besini devir. Canlari azaldikca yeminlerine sarilirlar - en tehlikeli anlari odur."), TEXT("Yemin agirdir, evlat; tasiyani da agirlastirir. Bu Buzbagli Kask'i tak; aklin sogukta bile berrak kalsin.") });
		Table.Add(FName(TEXT("Q_FrostboundSworn")), { TEXT("Gozculerle nobetciler arasinda bir kademe daha var, evlat: yeminini bozmayanlar. Ne hizlidirlar ne agir; dengeli, bu yuzden tehlikeli. Altisini durdur."), TEXT("Yeminliler geri cekildi. Al su Buyuk Can Iksirleri'ni; yemin ne kadar agirsa yara da o kadar derin olur.") });
		Table.Add(FName(TEXT("Q_FrostboundWarden")), { TEXT("Kapinin onunde son bir bekci var. Bil ki o fisiltiya degil, kapiya sadiktir; belki de bu diyarin en durust askeridir. Yine de yolumuz onun ardindan geciyor. Devir onu - ama dustugunde kapiya kulak ver."), TEXT("Dustu... ve kapi titredi, degil mi? Ben de duydum. Al su Buzbagli Kilic'i, evlat; korkarim yakinda guneyde lazim olacak.") });
		Table.Add(FName(TEXT("Q_FrostboundWatch")), { TEXT("Nobet bozulmadi, yalnizca el degistirdi. Sekiz nobetci daha devir; sabirli ol, yerlerinden kolay kimildamazlar."), TEXT("Nobet bozuldu. Bu Buyuk Mana Iksirleri'ni al; sabir da bir guctur, ama akli yenilemek icin icecegin bir sey gerekir.") });
		Table.Add(FName(TEXT("Q_Goblins")), { TEXT("Hos geldin, evlat. Cakili vadilerde goblin ceteleri pusu kuruyor; tek basina zayiftirlar ama sayilari coktur. Besini temizle ki kasabanin etrafi biraz nefes alsin."), TEXT("Ilk isin hayirli olsun. Al su Can Iksirleri'ni; yara almadan buyuyen maceraci gormedim.") });
		Table.Add(FName(TEXT("Q_Gold1000")), { TEXT("Kesende bin altin dursun, evlat. Parayi sevdigimden degil; savasin kaprisi cok, hazirliksiz maceracinin hesabi bellidir. Biriktir, ama kasayi bos birakma."), TEXT("Cebin dolu, aklin da dolu olsun. Altin kilic tutmaz ama kilici tasiyani besler.") });
		Table.Add(FName(TEXT("Q_Gold15000")), { TEXT("On bes bin altin biriktir, evlat; bu servet kilictan fazla kapi acar."), TEXT("On bes bin altin... Servet kilictan cok kapi acar, evlat. Kapiyi kim icin actigina dikkat et.") });
		Table.Add(FName(TEXT("Q_Gold30000")), { TEXT("Otuz bin altin biriktir, evlat; Akcakule'nin bile kolay gormedigi bir kese olsun."), TEXT("Otuz bin altin. Altin seni tasisin, sen altini tasima, evlat; yuk olan servet, servet sayilmaz.") });
		Table.Add(FName(TEXT("Q_Gold500")), { TEXT("Bes yuz altin biriktir, evlat; kesesi bos maceraciya pazar bile selam vermez."), TEXT("Bes yuz altin... Kucuk bir kese, ama buyuk bir aliskanligin basi. Aklini da kesen kadar dolu tut.") });
		Table.Add(FName(TEXT("Q_Gold5000")), { TEXT("Bes bin altin biriktir, evlat; vadide adin tuccarlar arasinda gecsin."), TEXT("Bes bin altin tasiyorsun artik. Kesen agirlastikca gozun de acilsin; parasi cok olanin dusmani da cok olur.") });
		Table.Add(FName(TEXT("Q_Gold50000")), { TEXT("Elli bin altin biriktir, evlat; bu yolun sonunda kasaya degil, ardinda biraktigina bakilir."), TEXT("Elli bin altin. Butun bolge adini aniyor, evlat. En zengin yolcu, geride bir iyilik birakandir; unutma.") });
		Table.Add(FName(TEXT("Q_GolemQuarry")), { TEXT("Golemler golun ardindaki ocakta yeniden dovuluyor, evlat; biri dusunce yerine yenisi cikiyor. Alti Magma Golemi daha kir, ocagin kozu sonsun."), TEXT("Ocak sondu, kor sogudu. Su Buyuk Mana Iksirleri'ni al; tasi yikan elin gucu de tukenir, doldurmayi unutma.") });
		Table.Add(FName(TEXT("Q_InfernalWraiths")), { TEXT("Buzulda gordugun hayaletlerin atesten ikizleri vadinin dibinde dolasiyor. Onlar dondurmaz, yakar; yandikca da ofkelenirler. Besini kov ki dibe inen yol acilsin."), TEXT("Dip bosaldi. Adamantin Zirh artik senin; vadinin dibinden donen, onu tasimayi hak etmistir.") });
		Table.Add(FName(TEXT("Q_Level20")), { TEXT("Deneyimini kanitla, evlat; yirminci seviyeye ulas, adin kapidan once gelsin."), TEXT("Yirminci seviye; artik adin yollarda duyuluyor, evlat. Al su Buyuk Can Iksirleri'ni, isine yarayacak.") });
		Table.Add(FName(TEXT("Q_Level30")), { TEXT("Ustalik acelesiz gelir, evlat. Otuzuncu seviyeye ulas ve kilicin sana boyun egsin."), TEXT("Usta Savasci... Kilici artik elin degil, aklin tutuyor, evlat. Al su Buyuk Mana Iksirleri; en zor ders de budur.") });
		Table.Add(FName(TEXT("Q_Level40")), { TEXT("Adini efsanelere yaz, evlat; kirkinci seviyeye ulas, ocak baslari seni anlatsin."), TEXT("Efsanevi Sovalye. Akcakule'nin ocak baslarinda adin aniliyor, evlat. Al su Buyuk Can Iksirleri; o hikayeleri bosa cikarma.") });
		Table.Add(FName(TEXT("Q_Level5")), { TEXT("Kendini gelistir, evlat; besinci seviyeye ulas, gerisini yol ogretir."), TEXT("Besinci seviye... Ilk adimlar hep zordur, evlat. Al su Buyuk Mana Iksirleri'ni; yolun daha yeni basliyor.") });
		Table.Add(FName(TEXT("Q_Level50")), { TEXT("Gucunu pekistir, evlat; ellinci seviyeye ulas, Kis Diyari'nin ruzgari da seni tanisin."), TEXT("Ellinci seviye... Artik acemi degil, ornek gosterilen birisin, evlat. Bu yuku gururla tasi; Fisilti hala susmadi.") });
		Table.Add(FName(TEXT("Q_Level65")), { TEXT("Kahramanlik cagina gir, evlat; altmis besinci seviyeye ulas ve omzundaki yuku tart."), TEXT("Kahraman diyorlar sana, evlat. Ama unvani yuceltmez seni; ayakta tutan, omzundaki yuktur. Onu tasimaya devam et.") });
		Table.Add(FName(TEXT("Q_Level80")), { TEXT("Yolculugunun zirvesine yuru, evlat; sekseninci seviyeye ulas, otesini goreceksin."), TEXT("Zirvedesin, evlat. Buradan her yol gorunur; ama unutma, dagin tepesinde de ruzgar eser.") });
		Table.Add(FName(TEXT("Q_MagmaGolems")), { TEXT("Karakaya'nin tas bekcisini hatirliyor musun? Vadinin lav golunu de onun atesten akrabalari bekliyor. Besini kir; yavas gelirler ama canlari azaldikca ofkeleri kabarir."), TEXT("Gol sessiz. Adamantin Bot'u giy; lavin kiyisinda bile saglam basarsin.") });
		Table.Add(FName(TEXT("Q_MagmaTyrant")), { TEXT("Vadinin hukumdari Magma Tirani. Buz Lordu sogugun tahtindaysa o da atesin tahtinda oturur - ikisi ayni fisiltinin iki yuzu. Onu devir; ama bil ki yanigi derine isler, ofkesi daglari sarsar."), TEXT("Dag sustu, evlat. Al su Adamantin Kilic'i. Fisilti hala bir yerlerde konusuyor; ama artik seni taniyor - ve senden korkuyor.") });
		Table.Add(FName(TEXT("Q_ObsidianRaiders")), { TEXT("Kara camdan kalkanlarla yola dokulen ork akincilari... Canlari azaldikca gozleri doner, ofkeleri katlanir. Besini dagit, ardindan reisi gor."), TEXT("Akincilar dagildi. Al su Obsidyen Zirh'i; atesin artigindan bile kalkan cikar, iste oyle.") });
		Table.Add(FName(TEXT("Q_ObsidianSentinels")), { TEXT("Gecidi agir bekciler tutuyor; yavaslar ama geri cekilmezler, darbeleri adimini agirlastirir. Besini devir ki yol acilsin."), TEXT("Gecit acik. Bu Obsidyen Kask senin; aklin keskin, basin saglam kalsin.") });
		Table.Add(FName(TEXT("Q_ObsidianStalkers")), { TEXT("Ates dagi sogudu, evlat; ama kara camin ustunde yeni bir bayrak dikildi. Golgelerde dolasan avcilar zehirle vurur. Besini durdur."), TEXT("Sirtlar biraz daha guvenli. Al su Obsidyen Bot'u; kara cam sivri, ayagin temiz basmali.") });
		Table.Add(FName(TEXT("Q_ObsidianWarlord")), { TEXT("Karakaya'da dusen reisin kan bagi sirtlarda orduyu yeniden topluyor. Ayni kandan, ayni ofke. Devir onu, evlat; ordusu bir daha toplanmasin."), TEXT("Kan bagi koptu, ordu bassiz. Al su Obsidyen Kilic'i. Ama fisilti buna ragmen susmadi - golgeler daha batida uzuyor.") });
		Table.Add(FName(TEXT("Q_OrcBerserkers")), { TEXT("Reislerini kaybeden orklar dagilmadi; en gozu donmusleri kuzey kampina cekildi. Aci onlari yildirmaz, cildirtir. Besini kir; o kamp ayakta kaldikca buzulda kimse guvende degil."), TEXT("Kamp dagildi. Bu Mithril Zirh artik senin; soguga da baltaya da gogus gerer.") });
		Table.Add(FName(TEXT("Q_OrcWarriors")), { TEXT("Karakaya Gecidi'ni baltali savascilar tutuyor; ordunun bel kemigi onlar. Dordunu devir, gecit biraz gevsesin."), TEXT("Baltalar sustu. Su Celik Migfer'i tak; ikinci bir vurusa firsat vermesin.") });
		Table.Add(FName(TEXT("Q_Orcs")), { TEXT("Dogu gecitlerinden orklar siziyor. Goblinlere benzemezler, evlat; iri, ofkeli ve vuruslari agirdir. Ucunu devir, ama onlara cok yaklasma."), TEXT("Ucunu de yendin demek. Fisiltinin ordusu yavas yavas gorunuyor artik.") });
		Table.Add(FName(TEXT("Q_RiftDepths")), { TEXT("Bekcilerin ardinda yarik derinlesiyor; mor isik her gece biraz daha asagidan geliyor. On bekci devir. Derinligi kapatamayiz belki, ama yolunu daraltabiliriz."), TEXT("Isik sonuklesti. Bu Buyuk Mana Iksirleri'ni sakla; derine bakan, gucunu cabuk tuketir.") });
		Table.Add(FName(TEXT("Q_RiftHerald")), { TEXT("Yarigi acan el bir habercinin eli. Haberciler savasi degil sozu getirir; ama getirdikleri soz kimi zaman savastan beterdir. Devir onu; dokunusu zehirler, cani azaldikca ofkelenir. Son sozunu iyi dinle."), TEXT("'Kul yuruyor,' dedi, oyle mi... Al su Yarik Kilici'ni, evlat. Yolun yine kuzeye; Kis seni ikinci kez bekliyor.") });
		Table.Add(FName(TEXT("Q_RiftKeepers")), { TEXT("Yarigin agzinda bekciler duruyor; kapatmak icin degil, acik tutmak icin. Besini devir. Agir gelirler, canlari azaldikca ofkeleri tasar."), TEXT("Agiz daraldi. Yarik Kaski'ni tak; o mor isiga uzun bakanin akli karisir.") });
		Table.Add(FName(TEXT("Q_RiftPurge")), { TEXT("Nobet dagildi ama yarigin agzi bos kalmadi, evlat; arayicilar yeniden toplaniyor. Onunu seyrelt ki habercinin yolunu acarken sirtin guvende olsun."), TEXT("Agiz seyreldi. Al su Buyuk Can Iksirleri'ni; zehrin goturdugunu bunlar geri getirir.") });
		Table.Add(FName(TEXT("Q_RiftSeekers")), { TEXT("Teraziyi hatirla, evlat: kuzeyde kapi gevsedi, guneyde toprak yarildi. Yaz'in dis yamaclarinda bir yarik acilmis, icinden arayicilar cikiyor. Kuzey Yolu'ndan geri in ve besini durdur; isiriklari zehirler."), TEXT("Ne aradiklarini bilmiyoruz; bulamadiklarini bilmek simdilik yeter. Al su Yarik Botu'nu; bu topraklar artik eskisi kadar saglam basmiyor.") });
		Table.Add(FName(TEXT("Q_RiftWalkers")), { TEXT("Yarigin en derininden yuruyerek cikanlar var; agir adimli, ofkeli. Sekizini durdur, canlari azalinca kudurduklarini unutma."), TEXT("Yuruyenler durdu. Al su Buyuk Mana Iksirleri'ni; yarigin otesini gormeden once zihnini topla.") });
		Table.Add(FName(TEXT("Q_RiftWatch")), { TEXT("Bir bekci dusunce yerine bir baskasi geciyor; nobet bozulmadikca yarigi acan el ortaya cikmaz. Alti bekci daha devir."), TEXT("Nobet dagildi; simdi yarigin icinden bir ses duyuluyor. Yarik Zirhi'ni giy - o ses seninle konusmak isteyecek.") });
		Table.Add(FName(TEXT("Q_RiftWhispers")), { TEXT("Yarigin agzinda birbirine fisildayan golgeler var, evlat; ne dediklerini anlama, yalnizca sustur. Sekizini devir; hizli hareket ederler, dokunuslari adimini agirlastirir."), TEXT("Fisiltilar kesildi... ama sessizlik daha da rahatsiz edici, degil mi? Al su Buyuk Can Iksirleri'ni; yariga bir kez daha bakacaksin.") });
		Table.Add(FName(TEXT("Q_ScorchedRaiders")), { TEXT("Alev Vadisi'ne yuruyen kavrulmus ork akincilari goruldu. Onunu dagit, evlat; vuruslari adimini agirlastirir, yaralaninca gozleri doner."), TEXT("Akincilar dagildi, vadinin kapisi bir sure sessiz kalir. Su Buyuk Mana Iksirleri'ni al; atesin onunde aklini serin tut.") });
		Table.Add(FName(TEXT("Q_ShadowAssassin")), { TEXT("Bir golge dolasiyor patikalarda; kervanlar sabaha sessiz variyor, kimse bagirmaya firsat bulamiyor. O golgeyi bul ve dagit - yoksa bir sonraki sessizlik senin olur."), TEXT("Kervanlar sabaha sag variyor artik. Al su Ejder Migferi'ni; golgeler seni bir daha arkandan bulmasin.") });
		Table.Add(FName(TEXT("Q_SpiderQueen")), { TEXT("Ormanin golgesi agirlasti, evlat; agaclarin arasi ipek ordu. O agin ortasinda bir ana bekler - onu yakmadan, orman bir daha nefes almayacak."), TEXT("Ag cozuldu, orman nefes aliyor. Al su Plaka Zirh'i; bir daha ipek gorursen once kalkanini dusun, evlat.") });
		Table.Add(FName(TEXT("Q_StoneGolem")), { TEXT("Karakaya bir zamanlar kendi bekcisini tastan yontmustu. Simdi o bekci yanlis bir sozle uyandi ve gecide vuruyor. Onu tekrar uykuya yatir; ama unutma, ofkesi buyudukce darbesi agirlasir."), TEXT("Bekci yeniden uykuda, gecit rahat soluyor. Al su Ejder Kilici'ni; tasi yikan elin hakki budur.") });
		Table.Add(FName(TEXT("Q_ThawStalkers")), { TEXT("Buz Lordu dusunce yamaclar cozulmeye basladi, evlat; eriyen buzun altindan sinsi avcilar cikiyor. Sekiz Cozulme Avcisi'ni durdur; hizlidirlar, vuruslari zehirler."), TEXT("Yamaclar nefes aliyor. Su Buyuk Mana Iksirleri'ni sakla; zehirle savasan, zihnini berrak tutmali.") });
		Table.Add(FName(TEXT("Q_Trolls")), { TEXT("Baslangic yoresindeki kiyilarda trol dolasiyor. Bir tanesi bile bir mufrezeyi dagitir, evlat. Ucunu sec, ama tek basina dalma."), TEXT("Sag dondun, bu da bir huner. Trole karsi cesaret degil, hesap kazanir.") });
		Table.Add(FName(TEXT("Q_VenomSpiders")), { TEXT("Buzun altinda sicak oyuklar var, evlat; sicaklik hayati cagirir, iyisini de kotusunu de. Orumcek Ana'nin soyu oraya yuva kurmus. Altisini ez, zehirleri kanina islemeden."), TEXT("Yuva sustu. Su Mithril Kask'i tak; aklin basinda, basin omzunda dursun.") });
		Table.Add(FName(TEXT("Q_Warlocks")), { TEXT("Karakaya'da orklari toplayan el, bir baltanin degil bir buyucunun eli. Solgun Fisilti'ya kanip insanligini degisenleri sustur; sozlerini keser kesmez, ordu da bassiz kalir."), TEXT("Fisiltinin sesi kisildi, ordu yonunu yitirdi. Al su Savas Baltasi'ni; bir sonraki soze keskin bir cevap olsun.") });
		Table.Add(FName(TEXT("Q_WinterColossus")), { TEXT("Karin altinda uyuyan buzdan devler var, evlat; hantal ama bir kez ofkelendi mi durmaz. Altisini yik; canlari azalinca kudurduklarini unutma."), TEXT("Devler yikildi, yer sallandi biraz. Al su Buyuk Mana Iksirleri'ni; bu iste aklini sakin tutan kazanir.") });
		Table.Add(FName(TEXT("Q_WinterGuardians")), { TEXT("Diyarin gecitlerini sabirli bekciler tutuyor; darbeleri avi yavaslatir. Besini devir ki ilerleyebilelim."), TEXT("Gecit acildi. Kis Botu'nu giy; buz saglam basana yol verir.") });
		Table.Add(FName(TEXT("Q_WinterHowls")), { TEXT("Firtinanin icinde uluyanlar ruzgar degil, evlat; Hukumdar'in surusu bu. Disleri adimini agirlastirir, sekizini devir ki suru bassiz kalsin."), TEXT("Uluma kesildi... Suru dagildi. Al su Buyuk Can Iksirleri'ni; bu sogukta kani sicak tutan her sey degerlidir.") });
		Table.Add(FName(TEXT("Q_WinterReavers")), { TEXT("Firtinanin icinden iri ork yagmacilar cikiyor; canlari azaldikca ofkeleri alevlenir. Besini dagit, geride kimse kalmasin."), TEXT("Yagma durdu. Bu Kis Kaski senin; firtina gozunu yaksa da aklin berrak kalsin.") });
		Table.Add(FName(TEXT("Q_WinterSovereign")), { TEXT("Diyarin tahtinda oturan, Uzun Kis'in asil sahibi. Buz Lordu bile bir vali sayilirmis yaninda. Devir onu; dokunusu bedenini agirlastirir, ofkesi firtina gibi kabarir."), TEXT("Firtina dindi, evlat... ufuk gorundu, goruyor musun? Al su Kis Kilici'ni; otesi artik senin yolun.") });
		Table.Add(FName(TEXT("Q_WinterStalkers")), { TEXT("Kuzey Yolu'nun sonunda Ayazdis'ten de beyaz bir toprak var, evlat: Kis Diyari. Karda iz birakmadan kosan izciler yolu tutuyor. Besini durdur; dokunuslari adimini agirlastirir."), TEXT("Izciler sustu. Al su Buyuk Can Iksirleri'ni; bu sogukta yara gec kapanir.") });
		Table.Add(FName(TEXT("Q_WinterWraiths")), { TEXT("Uzun Kis'in en eski oluleri bunlar, evlat; dokunuslari kani agirlastirir. Besini kov, ama sayilarini sayma."), TEXT("Oluler yatisiyor. Kis Zirhi'ni giy; soguk onlardan geliyor, senden degil.") });
		Table.Add(FName(TEXT("Q_Wolves")), { TEXT("Kuzey tepelerinin kurtlari yola inmeye basladi; geceleri ulumalari muhafizlarin uykusunu kaciriyor. Besini avla, ama suruden ayri dusenleri sec."), TEXT("Yollar sessiz. Al su Mana Iksirleri'ni; bundan sonra kafani da yormak zorunda kalacaksin.") });
		return Table;
	}
}

FString FMMOQuestDialogue::GetAcceptLine(FName QuestId)
{
	const FEntry* E = BuildTable().Find(QuestId);
	return E ? FString(E->Accept) : FString();
}

FString FMMOQuestDialogue::GetTurnInLine(FName QuestId)
{
	const FEntry* E = BuildTable().Find(QuestId);
	return E ? FString(E->TurnIn) : FString();
}
